import{_ as t,o,c as a,a2 as i}from"./chunks/framework.vLhlLNVn.js";const s="/assets/alias-iot-lampe.fBIqlii9.svg",m=JSON.parse('{"title":"VIS, Alexa, Google Home and Apple Home","description":"","frontmatter":{"order":7,"adapter":"wled","editLink":"https://github.com/DrozmotiX/ioBroker.wled/edit/main/docs/en/02.anleitungen/07.vis-und-smarthome.md"},"headers":[],"relativePath":"adapter/wled/anleitungen/vis-und-smarthome.md","filePath":"adapter/wled/anleitungen/vis-und-smarthome.md","lastUpdated":null}'),d={name:"adapter/wled/anleitungen/vis-und-smarthome.md"};function r(l,e,n,c,h,p){return o(),a("div",null,[...e[0]||(e[0]=[i('<h1 id="vis-alexa-google-home-and-apple-home" tabindex="-1">VIS, Alexa, Google Home and Apple Home <a class="header-anchor" href="#vis-alexa-google-home-and-apple-home" aria-label="Permalink to &quot;VIS, Alexa, Google Home and Apple Home&quot;">​</a></h1><p><a id="ready-made-vis-view-wled"></a></p><h2 id="is-there-a-ready-made-vis-view-for-controlling-wled" tabindex="-1">Is there a ready-made VIS view for controlling WLED? <a class="header-anchor" href="#is-there-a-ready-made-vis-view-for-controlling-wled" aria-label="Permalink to &quot;Is there a ready-made VIS view for controlling WLED?&quot;">​</a></h2><p><strong>In short:</strong> No, the adapter comes with neither a ready-made VIS view nor its own widgets. You build the controls from the standard VIS widgets and bind them to the states below. Alternatively, you embed the web interface of the WLED device with an iFrame.</p><h3 id="the-states-you-bind" tabindex="-1">The states you bind <a class="header-anchor" href="#the-states-you-bind" aria-label="Permalink to &quot;The states you bind&quot;">​</a></h3><p>All states are under <code>wled.0.&lt;device&gt;</code>. For a device with one segment, use segment <code>0</code>.</p><table tabindex="0"><thead><tr><th>Control</th><th>Widget</th><th>State</th><th>Value</th></tr></thead><tbody><tr><td>On/off</td><td>Switch</td><td><code>on</code></td><td><code>true</code> / <code>false</code></td></tr><tr><td>Brightness</td><td>Slider</td><td><code>bri</code></td><td>0 to 255</td></tr><tr><td>Color</td><td>Color picker</td><td><code>seg.0.col.0_HEX</code></td><td><code>#RRGGBB</code></td></tr><tr><td>Effect</td><td>Drop-down list</td><td><code>seg.0.fx</code></td><td>Number; the names come from the state</td></tr><tr><td>Palette</td><td>Drop-down list</td><td><code>seg.0.pal</code></td><td>Number; the names come from the state</td></tr><tr><td>Effect speed</td><td>Slider</td><td><code>seg.0.sx</code></td><td>Number</td></tr><tr><td>Effect intensity</td><td>Slider</td><td><code>seg.0.ix</code></td><td>Number</td></tr><tr><td>Preset</td><td>Buttons or number field</td><td><code>ps</code></td><td>Preset number</td></tr></tbody></table><h3 id="how-to-build-the-view" tabindex="-1">How to build the view <a class="header-anchor" href="#how-to-build-the-view" aria-label="Permalink to &quot;How to build the view&quot;">​</a></h3><ol><li>Create a new view in VIS.</li><li>Add a switch and bind it to <code>wled.0.&lt;device&gt;.on</code>.</li><li>Add a slider for <code>wled.0.&lt;device&gt;.bri</code> with minimum 0 and maximum 255. If you want 0 to 100 %, bind a percentage alias instead (see below).</li><li>Add a color picker and bind it to <code>wled.0.&lt;device&gt;.seg.0.col.0_HEX</code>.</li><li>Add two drop-down lists for <code>seg.0.fx</code> and <code>seg.0.pal</code>. The names of the effects and palettes are stored in the state itself, so you don&#39;t have to type them in.</li><li>For presets, add one button per preset that writes the preset number to <code>ps</code>.</li><li>Check the view in runtime mode: every change must be visible on the strip.</li></ol><div class="important custom-block github-alert"><p class="custom-block-title">IMPORTANT</p><p>For the color picker, use the HEX state <code>seg.0.col.0_HEX</code>, not the RGB state <code>seg.0.col.0</code>. The RGB state expects text like <code>[255,0,0]</code>, which a color picker doesn&#39;t deliver.</p></div><p><strong>Up to v0.9.2:</strong> If you write a HEX value, the adapter sets the white channel of RGBW strips to full, and the tertiary color <code>seg.0.col.2_HEX</code> has no effect.</p><p><strong>From v0.9.3:</strong> A 6-digit HEX value (<code>#RRGGBB</code>) leaves the white channel unchanged. With an 8-digit value (<code>#RRGGBBWW</code>) you set the white channel as well (<a href="https://github.com/DrozmotiX/ioBroker.wled/issues/907" target="_blank" rel="noreferrer">#907</a>). The tertiary color <code>2_HEX</code> takes effect (<a href="https://github.com/DrozmotiX/ioBroker.wled/issues/906" target="_blank" rel="noreferrer">#906</a>).</p><div class="tip custom-block github-alert"><p class="custom-block-title">TIP</p><p>The adapter doesn&#39;t provide a picture per preset. You solve that in VIS: create an image widget for each preset and make it visible only when <code>ps</code> has the matching number.</p></div><h3 id="embed-the-wled-web-interface" tabindex="-1">Embed the WLED web interface <a class="header-anchor" href="#embed-the-wled-web-interface" aria-label="Permalink to &quot;Embed the WLED web interface&quot;">​</a></h3><p>If you want all WLED functions in VIS, embed the device&#39;s web interface with an iFrame widget. As the address, enter <code>http://192.168.x.y</code>, the IP of your WLED device. The controls then work directly on the device, not through the adapter.</p><p><strong>See also:</strong></p><ul><li><a href="./../erste-schritte/erste-steuerung#use-brightness-percent-0-100">How do I use brightness as a percentage (0 to 100), for example for Alexa?</a></li><li><a href="./effekte-und-presets#switch-wled-presets-via-ps">How do I switch WLED presets via the state (ps) in VIS, Blockly or a script?</a></li><li><a href="#state-use-colour-picker-vis">Which state do I use for the color picker in VIS, and how do I show the current color?</a></li><li><a href="./../fehlerbehebung/farben-und-vis#vis-2-editor-freeze-pick">Why does the VIS 2 editor freeze when I pick seg.0.fx in the drop-down?</a></li></ul><p><a id="state-use-colour-picker-vis"></a></p><h2 id="which-state-do-i-use-for-the-color-picker-in-vis-and-how-do-i-show-the-current-color" tabindex="-1">Which state do I use for the color picker in VIS, and how do I show the current color? <a class="header-anchor" href="#which-state-do-i-use-for-the-color-picker-in-vis-and-how-do-i-show-the-current-color" aria-label="Permalink to &quot;Which state do I use for the color picker in VIS, and how do I show the current color?&quot;">​</a></h2><p><em>This section is still being written.</em></p><p><a id="choose-effect-palette-vis-as"></a></p><h2 id="how-do-i-choose-the-effect-and-the-palette-in-vis-as-a-drop-down" tabindex="-1">How do I choose the effect and the palette in VIS as a drop-down? <a class="header-anchor" href="#how-do-i-choose-the-effect-and-the-palette-in-vis-as-a-drop-down" aria-label="Permalink to &quot;How do I choose the effect and the palette in VIS as a drop-down?&quot;">​</a></h2><p><em>This section is still being written.</em></p><p><a id="connect-wled-iot-adapter-switch"></a></p><h2 id="how-do-i-connect-wled-to-the-iot-adapter-and-switch-effects-presets-and-color-via-alexa-or-google-home" tabindex="-1">How do I connect WLED to the iot adapter and switch effects, presets and color via Alexa or Google Home? <a class="header-anchor" href="#how-do-i-connect-wled-to-the-iot-adapter-and-switch-effects-presets-and-color-via-alexa-or-google-home" aria-label="Permalink to &quot;How do I connect WLED to the iot adapter and switch effects, presets and color via Alexa or Google Home?&quot;">​</a></h2><p><strong>In short:</strong> Up to v0.9.3 the adapter doesn&#39;t create a ready-made lamp for the iot adapter; from v0.10.0 you use the device&#39;s <code>light</code> channel. Without it, you build the lamp yourself with an alias device made of <code>on</code>, <code>bri</code> and <code>seg.0.col.0_HEX</code>, and give it a smart name in the iot adapter. You switch presets and effects via a helper state that Alexa or Google Home triggers like a scene.</p><p>The adapter&#39;s states have suitable roles: <code>on</code> is <code>switch.light</code>, <code>bri</code> is <code>level.brightness</code> with 0 to 255, and the color <code>seg.0.col.0_HEX</code> is <code>level.color.hex</code>. However, the iot adapter only recognises a light when these parts sit together in one structure. You create this structure yourself with an alias.</p><p><strong>From v0.10.0:</strong> The adapter creates this structure itself: every device has the channel <code>wled.0.&lt;device&gt;.light</code> with <code>on</code> (role <code>switch.light</code>), <code>dimmer</code> (role <code>level.dimmer</code>, 0 to 100 %) and <code>rgb</code> (role <code>level.color.rgb</code>, primary color of the main segment as HEX). The type detector recognizes the channel as a color light (<a href="https://github.com/DrozmotiX/ioBroker.wled/issues/328" target="_blank" rel="noreferrer">#328</a>). Assign <code>light</code> to a room and a function in the &quot;Enums&quot; tab, or give it a smart name in the iot adapter, and let Alexa or Google Home search for new devices. You then only need the alias steps below for segments other than the main segment. You still switch presets and effects as described below under &quot;Presets and effects as a scene&quot;.</p><p><img src="'+s+`" alt="Diagram: Alexa or Google Home use a smart name in the iot adapter to address an alias device with on, brightness in percent and color, which points to on, bri and seg.0.col.0_HEX of the WLED device. For a preset, the smart name triggers a helper state, and a script writes the preset number to ps."></p><h3 id="on-off-brightness-and-color-as-a-lamp" tabindex="-1">On/off, brightness and color as a lamp <a class="header-anchor" href="#on-off-brightness-and-color-as-a-lamp" aria-label="Permalink to &quot;On/off, brightness and color as a lamp&quot;">​</a></h3><ol><li><p>In Admin, open the &quot;Objects&quot; tab and create a folder for the lamp under <code>alias.0</code>, for example <code>alias.0.WLED.LivingRoom</code>.</p></li><li><p>Create three states in it:</p><table tabindex="0"><thead><tr><th>State in the alias</th><th>Role</th><th>Type</th><th>Target (<code>alias.id</code>)</th><th>Conversion</th></tr></thead><tbody><tr><td><code>on</code></td><td><code>switch.light</code></td><td><code>boolean</code></td><td><code>wled.0.&lt;device&gt;.on</code></td><td>none</td></tr><tr><td><code>brightness</code></td><td><code>level.dimmer</code>, 0 to 100, unit <code>%</code></td><td><code>number</code></td><td><code>wled.0.&lt;device&gt;.bri</code></td><td>Read <code>Math.round(val / 2.55)</code>, write <code>Math.ceil(val * 2.55)</code></td></tr><tr><td><code>color</code></td><td><code>level.color.rgb</code></td><td><code>string</code></td><td><code>wled.0.&lt;device&gt;.seg.0.col.0_HEX</code></td><td>none</td></tr></tbody></table></li><li><p>Open the iot adapter&#39;s tab, find the alias device there and give it a smart name, for example &quot;Living room strip&quot;.</p></li><li><p>Let Alexa or Google Home search for new devices.</p></li><li><p>Test it with &quot;Living room strip to 50 percent&quot;: <code>wled.0.&lt;device&gt;.bri</code> should jump to <code>128</code>.</p></li></ol><p>How to create the percentage alias in detail is described under <a href="./../erste-schritte/erste-steuerung#use-brightness-percent-0-100">How do I use brightness as a percentage (0 to 100), for example for Alexa?</a>.</p><div class="tip custom-block github-alert"><p class="custom-block-title">TIP</p><p>If you only need on/off and brightness, a smart name directly on <code>wled.0.&lt;device&gt;.bri</code> is often enough. Because <code>bri</code> has a minimum and a maximum, the iot adapter converts percentages to 0 to 255 by itself.</p></div><h3 id="presets-and-effects-as-a-scene" tabindex="-1">Presets and effects as a scene <a class="header-anchor" href="#presets-and-effects-as-a-scene" aria-label="Permalink to &quot;Presets and effects as a scene&quot;">​</a></h3><p>Voice assistants don&#39;t know about WLED presets or effects. So for each preset you create a helper state that Alexa or Google Home switches on, and a small script writes the preset number to <code>ps</code>.</p><ol><li><p>Create a state of type <code>boolean</code> with the role <code>button</code>, for example <code>0_userdata.0.WLED.Fireplace</code>.</p></li><li><p>Give it a smart name in the iot adapter, for example &quot;Fireplace&quot;.</p></li><li><p>Create this script in the JavaScript adapter. Replace the <code>5</code> with the number of your preset in WLED:</p><div class="language-js vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">js</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">on</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">({ id: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;0_userdata.0.WLED.Fireplace&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, val: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, ack: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">false</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> }, () </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=&gt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> {</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">    setState</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;wled.0.&lt;device&gt;.ps&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">5</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">);</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">});</span></span></code></pre></div></li><li><p>Say &quot;Alexa, turn on Fireplace&quot;. <code>wled.0.&lt;device&gt;.ps</code> should jump to <code>5</code>.</p></li></ol><p>In the same way you can write an effect instead of <code>ps</code>, for example <code>setState(&#39;wled.0.&lt;device&gt;.seg.0.fx&#39;, 9)</code>. How writing <code>ps</code> works in detail and what to watch out for is described under <a href="./effekte-und-presets#switch-wled-presets-via-ps">How do I switch WLED presets via the state (ps) in VIS, Blockly or a script?</a>.</p><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p>WLED itself has its own Alexa integration that works without ioBroker. It runs directly in the WLED firmware and has nothing to do with the adapter.</p></div><h3 id="limits" tabindex="-1">Limits <a class="header-anchor" href="#limits" aria-label="Permalink to &quot;Limits&quot;">​</a></h3><ul><li><strong>A color doesn&#39;t stop an effect.</strong> A color command only writes the colors of the segment. If an effect is running, it keeps running with the new color. If you want a steady color, select a preset with a single-color effect first.</li><li><strong>One alias per segment.</strong> The alias device above only controls segment <code>0</code>. For other segments you need separate aliases on <code>seg.&lt;segment&gt;.on</code>, <code>seg.&lt;segment&gt;.bri</code> and <code>seg.&lt;segment&gt;.col.0_HEX</code>.</li><li><strong>Effects and palettes only via helper states.</strong> There is no direct selection by voice.</li><li><strong>No feedback for scenes.</strong> The helper state doesn&#39;t show whether the preset is still active.</li></ul><p><strong>Up to v0.9.2:</strong> If the iot adapter writes a color to an RGBW strip, the adapter switches the white channel to full.</p><p><strong>From v0.9.3:</strong> A 6-digit color (<code>#RRGGBB</code>) leaves the white channel unchanged (<a href="https://github.com/DrozmotiX/ioBroker.wled/issues/907" target="_blank" rel="noreferrer">#907</a>).</p><p><strong>See also:</strong></p><ul><li><a href="#ready-made-vis-view-wled">Is there a ready-made VIS view for controlling WLED?</a></li><li><a href="./farbe#control-white-channel-rgbw-sk6812">How do I control the white channel (RGBW, SK6812, warm white)?</a></li></ul><p><a id="colour-picker-wled-apple-home"></a></p><h2 id="how-do-i-get-a-color-picker-for-wled-in-apple-home-yahka" tabindex="-1">How do I get a color picker for WLED in Apple Home (Yahka)? <a class="header-anchor" href="#how-do-i-get-a-color-picker-for-wled-in-apple-home-yahka" aria-label="Permalink to &quot;How do I get a color picker for WLED in Apple Home (Yahka)?&quot;">​</a></h2><p><em>This section is still being written.</em></p>`,47)])])}const u=t(d,[["render",r]]);export{m as __pageData,u as default};
